const TZ = 'Asia/Ho_Chi_Minh';
// The procedures are in the instructions (Content agent: context). The task names one and says where the final answer goes.
const REPORT = 'Your final answer is the report sent to the team: progress on each goal, what worked, what did not, what you changed in your playbook and why, what you will test next, and what you need from them. At most 15 lines, plain text.';
const now = DateTime.now().setZone(TZ);
const s = (v) => (v ?? '').toString().trim();
let input = {};
let mode = 'shift';
if ($('When called').isExecuted) {
  input = $('When called').first().json || {};
  mode = ['command', 'event', 'shift', 'review'].includes(input.mode) ? input.mode : 'command';
} else if ($('Weekly review').isExecuted) {
  mode = 'review';
}
// hand_off sends procedure and brief; command and args are the older names.
const procedure = s(input.procedure || input.command) || (mode === 'review' ? 'review' : '');
const brief = s(input.brief) || [s(input.args), s(input.text)].filter(Boolean).join('\n\n');
let task;
if (mode === 'shift') task = 'Run the shift procedure. Your final answer is your work log entry: 2 to 4 lines on what you did and why. It is not sent to the team.';
else if (mode === 'event') task = `Something happened: ${input.text}\n\nDo the work that follows from it with your tools. Your final answer is your work log entry (1 to 3 lines), not sent to the team.`;
else if (mode === 'review' && !input.reply_to) task = `Run the review procedure. ${REPORT}`;
else task = `The front desk handed you this work from the team: run the ${procedure || 'fitting'} procedure.\n\nBrief:\n<<<\n${brief}\n>>>\n\n${procedure === 'review' ? REPORT : "Your final answer is posted in the team's thread: what you did and why, briefly."}`;
return [{ json: { mode, task, reply_to: s(input.reply_to), started_at: now.toISO() } }];

const TZ = 'Asia/Ho_Chi_Minh';
// The NocoDB node nests a row as { id, id_fields, fields }.
const rowsOf = (name) => $(name).all()
  .map((i) => i.json || {})
  .filter((j) => j.id !== undefined && j.id !== null)
  .map((j) => ({ Id: j.id, ...(j.fields || {}) }));
const settingsOf = (name) => Object.fromEntries(
  rowsOf(name).filter((r) => r.key).map((r) => [r.key, (r.value ?? '').toString().trim()]));
const parseDt = (s) => DateTime.fromISO(String(s || '').trim().replace(' ', 'T'), { setZone: true }).setZone(TZ);
const parseDate = (s) => DateTime.fromISO(String(s || '').trim().slice(0, 10), { zone: TZ });
// settings.post_window, e.g. "07:00-22:00": the times posts may go out.
const windowOf = (v) => {
  const m = String(v || '').match(/(\d{1,2}):(\d{2})\s*-\s*(\d{1,2}):(\d{2})/);
  return m ? { from: `${m[1].padStart(2, '0')}:${m[2]}`, to: `${m[3].padStart(2, '0')}:${m[4]}` } : { from: '07:00', to: '22:00' };
};
const validTime = (t) => /^([01]\d|2[0-3]):[0-5]\d$/.test(t);
const slotOf = (dt) => { const h = Math.floor(dt.hour / 3) * 3; return `${String(h).padStart(2, '0')}-${String(h + 3).padStart(2, '0')}h`; };

// The report always lists the playbook changes, whatever the agent wrote.
// The NocoDB filter compares dates only; keep the changes made during this run.
const started = parseDt($('Task').first().json.started_at);
const changes = rowsOf('Changes this review').filter((e) => parseDt(e.created_at) >= started).map((e) => `- ${String(e.text || '').split('\n\nPrevious text:')[0]}`);
const out = String($('Agent').first().json.output || '').trim();
return [{ json: { reply_to: $('Task').first().json.reply_to, text: `📋 Weekly review\n\n${out}${changes.length ? `\n\nPlaybook changes:\n${changes.join('\n')}` : '\n\nNo playbook changes this week.'}\n\nReply to correct me.` } }];

